int map_user_io_vectors(struct request_queue *q, struct request *rq,
                        struct rq_map_data *map_data,
                        const struct iov_iter *iter, gfp_t gfp_mask) {
    int ret = 0;
    size_t iov_offset = 0;

    if (!q || !rq || !map_data || !iter)
        return -EINVAL;

    if (iov_iter_alignment(iter) != 0)
        return -EINVAL;

    while (iov_iter->nr_segs && iov_offset < iter->count) {
        struct iovec *iov = iov_iter_iovec(iter) + iov_offset;
        size_t len = iov->iov_len;
        void *addr = iov->iov_base;

        if (!addr || !len) {
            ret = -EINVAL;
            break;
        }

        struct bio *bio = bio_map_user(q->bs, addr, len, gfp_mask, &ret);
        if (!bio) {
            ret = -EINVAL;
            break;
        }

        bio->bi_private = rq;
        rq->bio = bio;

        if (map_data->offset)
            bio->bi_sector += map_data->offset;

        submit_bio(REQ_OP_READ, bio);
        iov_offset++;
    }

    if (ret != 0) {
        while (rq->bio) {
            struct bio *bio = rq->bio;
            rq->bio = bio->bi_next;
            bio_put(bio);
        }
    }

    return ret;
}

int blk_rq_map_user(struct request_queue *q, struct request *rq,
                    struct rq_map_data *map_data,
                    const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio = NULL;
    struct bio *head = NULL;
    size_t len = iov_iter_count(iter);
    int ret = 0;

    if (!len || !iov_iter_is_user(iter))
        return -EINVAL;

    if (map_data)
        rq->end_request = map_data->end_io;

    if (iov_iter_npages(iter, INT_MAX) > q->max_segments)
        return -EINVAL;

    while (iov_iter_count(iter)) {
        struct bio *new;
        struct page *page;
        size_t size = min(iov_iter_count(iter), (size_t)queue_max_segment_size(q));

        page = alloc_page(gfp_mask);
        if (!page) {
            ret = -ENOMEM;
            goto out;
        }

        if (copy_from_iter(PageHighMem(page) ? kmap_local(page) : page_address(page),
                            size, iter) != size) {
            __free_page(page);
            ret = -EFAULT;
            goto out;
        }

        new = bio_alloc(GFP_KERNEL, 1);
        if (!new) {
            __free_page(page);
            ret = -ENOMEM;
            goto out;
        }

        bio_add_page(new, page, size, 0);
        new->bi_io_vec[0].bv_len = size;

        if (!bio) {
            bio = new;
            head = bio;
        } else {
            bio->bi_next = new;
            bio = new;
        }
    }

    rq->data_len = len;
    rq->__data_len = len;
    rq->bio = head;

    ret = 0;
out:
    if (ret < 0) {
        struct bio *b, *n;
        for (b = head; b; b = n) {
            n = b->bi_next;
            bio_put(b);
        }
    }
    return ret;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data,
                const struct iov_iter *iter, gfp_t gfp_mask) {
    size_t len = iter->count;
    struct bio *bio = NULL;
    struct bio *head = NULL;
    struct iovec *iov;
    size_t nr_segs = 0;
    size_t i, seg_count;
    int ret = 0;

    if (!iov_iter_count(iter))
        return 0;

    seg_count = iov_iter_nseg(iter);
    if (seg_count > BIO_MAX_PAGES)
        return -EINVAL;

    iov = kcalloc(seg_count, sizeof(*iov), gfp_mask & ~__GFP_ZERO);
    if (!iov)
        return -ENOMEM;

    iov_iter_copy_to_user_iovec(iov, iter, seg_count);

    for (i = 0; i < seg_count; i++) {
        struct bio *b;

        if (iov[i].iov_len == 0)
            continue;

        b = bio_alloc(GFP_NOIO, 1);
        if (!b) {
            ret = -ENOMEM;
            goto out;
        }

        if (bio_add_page(b, iov[i].iov_base, iov[i].iov_len, 0) != iov[i].iov_len) {
            ret = -EINVAL;
            bio_put(b);
            goto out;
        }

        if (!head)
            head = b;
        else
            bio_chain(rq->bio, b);
        rq->bio = b;
    }

    if (!head)
        ret = -EINVAL;
    else
        rq->cmd_flags |= REQ_USER_MAPPED;

out:
    kfree(iov);
    return ret;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data, const struct iov_iter *iter, gfp_t gfp_mask) {
    int ret = 0;
    struct bio *bio = NULL;
    size_t bytes_mapped = 0;

    if (!q || !rq || !map_data || !iter) {
        return -EINVAL;
    }

    // Check if a copy is needed due to misalignment
    if (((uintptr_t)iter->iov->iov_base & (queue_dma_alignment(q))) != 0) {
        // Data is misaligned; data copy is required
        return -EINVAL;
    }

    while (iov_iter_count(iter) > 0) {
        struct bio *new_bio = bio_kmalloc(gfp_mask, 1);
        if (!new_bio) {
            ret = -EINVAL;
            goto cleanup;
        }

        // Use helper function to map the I/O vectors to the bio
        if (bio_add_page(new_bio, iter->iov->iov_base, iov_iter_single_seg(iter), 0) <= 0) {
            ret = -EINVAL;
            goto cleanup;
        }

        bytes_mapped += new_bio->bi_iter.bi_size;

        // Chain the bio to the request
        if (!rq->biotail) {
            rq->bio = new_bio;
        } else {
            rq->biotail->bi_next = new_bio;
        }
        rq->biotail = new_bio;
    }

    // Set the appropriate flags if mapping was successful
    rq->cmd_flags |= REQ_COPY;

    return 0;

cleanup:
    if (bio) {
        bio_unmap_user(bio);
        bio_put(bio);
    }
    return ret;
}

int map_user_io_vectors(struct request_queue *q, struct request *rq,
                        struct rq_map_data *map_data,
                        const struct iov_iter *iter, gfp_t gfp_mask) {
    size_t total_len = iov_iter_count(iter);
    struct bio *bio = NULL;
    struct bio *head = NULL;
    struct bio_vec bvec;
    struct iov_iter i = *iter;
    int nr_segs = 0;
    int ret = 0;
    unsigned int align = map_data->offset & (QUEUE_ALIGN - 1);

    if (align && !iov_iter_is_bvec(iter)) {
        /* Data is not aligned, need to copy */
        bio = bio_alloc(GFP_NOIO, 1);
        if (!bio)
            return -EINVAL;

        ret = iov_iter_get_pages(i, bio->bi_io_vec, BIO_MAX_PAGES, 1, &i);
        if (ret <= 0) {
            bio_put(bio);
            return -EINVAL;
        }

        bio->bi_sector = map_data->offset + (i.iov_offset & ~(queue_logical_block_size(q) - 1));
        bio->bi_bdev = map_data->bdev;
        bio->bi_end_io = NULL;
        bio->bi_private = NULL;
        bio->bi_flags |= BIO_UPTODATE;
        nr_segs = 1;
    } else {
        while (iov_iter_next_segment(&i)) {
            bio = bio_alloc(GFP_NOIO, 1);
            if (!bio) {
                ret = -EINVAL;
                goto cleanup;
            }

            iov_iter_get_bvec(&i, &bvec);
            bio_add_page(bio, bvec.bv_page, bvec.bv_len, bvec.bv_offset);
            bio->bi_sector = map_data->offset + (i.iov_offset & ~(queue_logical_block_size(q) - 1));
            bio->bi_bdev = map_data->bdev;
            bio->bi_end_io = NULL;
            bio->bi_private = NULL;
            bio->bi_flags |= BIO_UPTODATE;
            nr_segs++;
        }
    }

    if (!nr_segs) {
        ret = -EINVAL;
        goto cleanup;
    }

    rq->cmd_type = REQ_TYPE_BLOCK_PC;
    rq->cmd_flags |= REQ_FAIL_IF_ZERO;
    rq->nr_phys_segments = nr_segs;
    rq->data_len = total_len;
    rq->bio = head;

    return 0;

cleanup:
    while (head) {
        bio = head;
        head = bio->bi_next;
        bio_put(bio);
    }
    return ret;
}
